package org.transittr;
import android.content.*;import android.os.*;import android.graphics.Color;import android.graphics.Typeface;import android.view.*;import android.widget.*;import java.util.*;import org.json.*;
/** Departure board for the system screensaver and TV preview. */
public final class TvBoard extends LinearLayout {
 private static final int PAPER=0xfff1f5f2,MUTED=0xffa6b8b0,ACCENT=0xff90d5bb;private final Handler handler=new Handler();private final LinearLayout rows;private final TextView state,clock;private boolean running;private int generation,page;
 public TvBoard(Context c){super(c);setOrientation(VERTICAL);setPadding(dp(58),dp(28),dp(58),dp(24));setBackgroundColor(0xff0c1514);LinearLayout header=new LinearLayout(c);header.setGravity(Gravity.CENTER_VERTICAL);addView(header,new LayoutParams(-1,dp(42)));LinearLayout identity=new LinearLayout(c);identity.setOrientation(VERTICAL);TextView brand=label("TRANSIT TR",14,PAPER);brand.setTypeface(Typeface.DEFAULT,Typeface.BOLD);identity.addView(brand);TextView eyebrow=label("CANLI ULAŞIM PANOSU",11,MUTED);identity.addView(eyebrow);header.addView(identity,new LayoutParams(0,-2,1));clock=label("--:--",30,PAPER);clock.setTypeface(Typeface.DEFAULT,Typeface.BOLD);header.addView(clock);View rule=new View(c);rule.setBackgroundColor(0xff39504a);LayoutParams line=new LayoutParams(-1,dp(1));line.topMargin=dp(14);addView(rule,line);LinearLayout column=new LinearLayout(c);column.setPadding(0,dp(10),0,dp(7));TextView left=label("HAT  /  DURAK",11,MUTED),right=label("VARIŞ",11,MUTED);column.addView(left,new LayoutParams(0,-2,1));column.addView(right);addView(column);rows=new LinearLayout(c);rows.setOrientation(VERTICAL);addView(rows,new LayoutParams(-1,0,1));state=label("",11,MUTED);state.setPadding(0,dp(10),0,0);addView(state);}
 private TextView label(String value,int size,int color){TextView t=new TextView(getContext());t.setText(value);t.setTextSize(size);t.setTextColor(color);return t;}private int dp(int n){return (int)(n*getResources().getDisplayMetrics().density+.5f);}
 public void start(){running=true;refresh();}public void stop(){running=false;generation++;handler.removeCallbacksAndMessages(null);}
 private void refresh(){if(!running)return;final int ticket=++generation;clock.setText(android.text.format.DateFormat.format("HH:mm",System.currentTimeMillis()));final ArrayList<WidgetFavorites.Entry> entries=WidgetFavorites.all(getContext());rows.removeAllViews();if(entries.isEmpty()){TextView empty=label("Henüz durak eklenmedi",24,PAPER);empty.setGravity(Gravity.CENTER_VERTICAL);rows.addView(empty,new LayoutParams(-1,0,1));state.setText("Uygulama → Ayarlar → Pano duraklarını düzenle");return;}final int start=(page*4)%entries.size(),count=Math.min(4,entries.size()-start);page=(start+count>=entries.size())?0:page+1;state.setText("Veriler alınıyor…");final TextView[] values=new TextView[count];for(int i=0;i<count;i++){WidgetFavorites.Entry e=entries.get(start+i);LinearLayout row=new LinearLayout(getContext());row.setGravity(Gravity.CENTER_VERTICAL);TextView route=label(e.line,26,ACCENT);route.setTypeface(Typeface.DEFAULT,Typeface.BOLD);row.addView(route,new LayoutParams(dp(90),-2));LinearLayout info=new LinearLayout(getContext());info.setOrientation(VERTICAL);TextView city=label(e.label.length()>0?e.label:WidgetFavorites.cityName(e.city),18,PAPER);city.setSingleLine(true);info.addView(city);info.addView(label("Durak "+e.stop,12,MUTED));row.addView(info,new LayoutParams(0,-2,1));values[i]=label("—",27,PAPER);values[i].setTypeface(Typeface.DEFAULT,Typeface.BOLD);row.addView(values[i]);rows.addView(row,new LayoutParams(-1,0,1));if(i<count-1){View divider=new View(getContext());divider.setBackgroundColor(0xff273a35);rows.addView(divider,new LayoutParams(-1,dp(1)));}}new Thread(new Runnable(){public void run(){for(int i=0;i<count;i++){if(!running||ticket!=generation)return;final int index=i;String text;try{JourneyData.Snapshot snap=WidgetArrivals.fetch(entries.get(start+i));JSONObject result=WidgetArrivals.select(snap,entries.get(start+i),System.currentTimeMillis());text=result.optString("eta","—");}catch(Exception e){text="Bağlantı yok";}final String result=text;handler.post(new Runnable(){public void run(){if(running&&ticket==generation)values[index].setText(result);}});}handler.post(new Runnable(){public void run(){if(running&&ticket==generation){state.setText("ULAŞIM SERVİSLERİ   ·   GÜNCELLEME "+android.text.format.DateFormat.format("HH:mm",System.currentTimeMillis())+(entries.size()>4?"   ·   "+(start+1)+"–"+(start+count)+" / "+entries.size():""));handler.postDelayed(new Runnable(){public void run(){refresh();}},60000);}}});}}).start();}
}
